-- PT117-S2-Q3. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT117-S2-Q3$batch03$ AND q.stimulus=$batch03$In the past, combining children of different ages in one classroom was usually a failure; it resulted in confused younger children, who were given inadequate attention and instruction, and bored older ones, who had to sit through previously learned lessons. Recently, however, the practice has been revived with excellent results. Mixed-age classrooms today are stimulating to older children and enable younger children to learn much more efficiently than in standard classrooms.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent discrepancy in the passage?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT117-S2-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT117-S2-Q3$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S2-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT117-S2-Q3$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Mixed-age classrooms used to fail: younger children were confused and older ones bored.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Today's mixed-age classrooms work very well?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Something must be different now. The old problems came from giving one lesson to children at different levels. What teaching approach would let both ages work well together?$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a change in how mixed-age classrooms run today that fixes the old problems.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT117-S2-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Larger classes mean less attention per child, which should make things worse, not better.$batch03$), ($batch03$B$batch03$, $batch03$Past classrooms being better equipped makes their failure harder to explain and today's success more surprising.$batch03$), ($batch03$C$batch03$, $batch03$Today's classrooms use group projects that engage students of different ages. That replaces the one-level lesson that confused the young and bored the old.$batch03$), ($batch03$D$batch03$, $batch03$A wider range of ages should make the old problems worse.$batch03$), ($batch03$E$batch03$, $batch03$Whether teachers were once in mixed-age classrooms does not explain why the classrooms now work.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT117-S2-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
